#include <bits/stdc++.h>

int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

int main() {
	int n = ri();
	int a[n];
	for (auto &i : a) i = ri();

	int res = 2000000000;
	for (int i = 0; i < 1 << (n - 1); i++) {
		int xored = 0;
		int ored = 0;
		for (int j = 0; j <= n; j++) {
			if (j < n) ored |= a[j];
			if (j == n || (i >> j & 1)) xored ^= ored, ored = 0;
		}
		res = std::min(res, xored);
	}

	printf("%d\n", res);
	return 0;
}

use itertools::Itertools;
use proconio::input;
use std::ops::BitOr;

fn main() {
    input! { n: usize, a: [u32; n] }
    let mut dp = vec![Vec::new(); n + 1];
    dp[0].push(0);
    for r in 1..=n {
        for l in 0..r {
            let or = a[l..r].iter().copied().fold(0, BitOr::bitor);
            let xor = dp[l].iter().map(|&x| x ^ or).collect_vec();
            dp[r].extend(xor);
        }
    }
    println!("{}", dp[n].iter().min().unwrap());
}
